<script setup lang="ts">
const result = defineModel<any>('result', { default: null })
defineProps<{ fileName: string; extracting: boolean; saving: boolean; chemicalFields: Array<{ key: string; label: string; unit: string }>; drxOptions: unknown[]; petrografiaOptions: unknown[]; chemicalText: (text: string) => string }>()
