const extraFields = [['pn', 'Poder Neutralizante PN (%)'], ['blancura', 'Blancura (%)'], ['tamano_particula', 'Tamaño Partícula (µm)'], ['humedad', 'Humedad (%)'], ['cao_disponible', 'CaO Disponible (%)'], ['cao_reactivo', 'CaO Reactivo (%)'], ['resistencia', 'Resistencia (MPa)'], ['absorcion', 'Absorción (%)']]
</script>

