      <OriginalCompositionTable :originales="result.datos.originales" :chemical-text="chemicalText" />
      <details v-if="Object.keys(result.datos.metadatos || {}).length" class="mb-4 text-sm"><summary class="cursor-pointer font-semibold">Información del ensayo</summary><dl class="mt-2 space-y-1"><div v-for="(value, field) in result.datos.metadatos" :key="field"><dt class="font-medium">{{ field }}</dt><dd>{{ value }}</dd></div></dl></details>
