        <div class="flex justify-end gap-3 border-t border-slate-100 pt-6"><UButton color="neutral" variant="ghost" @click="$emit('clear-result')">Limpiar</UButton><UButton type="submit" color="success" icon="i-heroicons-circle-stack" :loading="saving">Evaluar y Registrar Muestra</UButton></div>
